import {
  CUSTOM_NAMESPACE,
  PROTOCOL_VERSION,
  RECEIVER_CAPABILITIES,
} from "../protocol/constants";
import type {
  DiagnosticMessage,
  ReadyMessage,
  SnapshotRequestMessage,
} from "../protocol/types";
import type { ReceiverStore } from "../state/receiverStore";

interface CustomMessageEvent {
  data: unknown;
  senderId: string;
}

interface SenderConnectedEvent {
  senderId: string;
}

interface CastReceiverOptionsLike {
  customNamespaces: Record<string, string>;
}

interface CastReceiverContextLike {
  addCustomMessageListener(
    namespace: string,
    listener: (event: CustomMessageEvent) => void,
  ): void;
  addEventListener(eventType: string, listener: (event: SenderConnectedEvent) => void): void;
  sendCustomMessage(namespace: string, senderId: string | undefined, message: object): void;
  start(options: CastReceiverOptionsLike): void;
}

interface CastFrameworkGlobal {
  framework: {
    CastReceiverContext: {
      getInstance(): CastReceiverContextLike;
    };
    CastReceiverOptions: new () => CastReceiverOptionsLike;
    system: {
      EventType: {
        SENDER_CONNECTED: string;
      };
      MessageType: {
        JSON: string;
      };
    };
  };
}

declare global {
  interface Window {
    cast?: CastFrameworkGlobal;
  }
}

function createInstanceId(): string {
  return globalThis.crypto?.randomUUID?.() ?? `receiver-${Date.now()}-${Math.random()}`;
}

function relatedMessageId(input: unknown): string | undefined {
  if (input === null || typeof input !== "object" || Array.isArray(input)) return undefined;
  const messageId = (input as Record<string, unknown>).messageId;
  return typeof messageId === "string" && messageId.length > 0 ? messageId : undefined;
}

export function initializeCastBridge(store: ReceiverStore): boolean {
  const castGlobal = window.cast;
  if (castGlobal === undefined) return false;

  const context = castGlobal.framework.CastReceiverContext.getInstance();
  const receiverInstanceId = createInstanceId();
  let sequence = 0;
  let invalidRequestTimer: ReturnType<typeof setTimeout> | null = null;

  const nextMessageId = (type: string): string =>
    `${receiverInstanceId}:${type}:${String(++sequence)}`;

  const send = (senderId: string | undefined, message: object): void => {
    context.sendCustomMessage(CUSTOM_NAMESPACE, senderId, message);
  };

  const sendReady = (senderId: string): void => {
    const message: ReadyMessage = {
      protocolVersion: PROTOCOL_VERSION,
      messageType: "ready",
      messageId: nextMessageId("ready"),
      receiverInstanceId,
      supportedProtocol: { min: PROTOCOL_VERSION, max: PROTOCOL_VERSION },
      capabilities: RECEIVER_CAPABILITIES,
    };
    send(senderId, message);
  };

  const sendInvalidSnapshotResponse = (
    senderId: string,
    input: unknown,
    details: string,
  ): void => {
    const diagnostic: DiagnosticMessage = {
      protocolVersion: PROTOCOL_VERSION,
      messageType: "diagnostic",
      messageId: nextMessageId("diagnostic"),
      severity: "WARNING",
      code: "INVALID_SNAPSHOT",
      relatedMessageId: relatedMessageId(input),
      details: details.slice(0, 240),
    };
    send(senderId, diagnostic);

    if (invalidRequestTimer !== null) clearTimeout(invalidRequestTimer);
    invalidRequestTimer = setTimeout(() => {
      const current = store.snapshot;
      const request: SnapshotRequestMessage = {
        protocolVersion: PROTOCOL_VERSION,
        messageType: "snapshot-request",
        messageId: nextMessageId("snapshot-request"),
        receiverInstanceId,
        reason: "INVALID_SNAPSHOT",
        lastAppliedGameSessionId: current?.gameSessionId ?? null,
        lastAppliedRevision: current?.revision ?? null,
      };
      send(senderId, request);
      invalidRequestTimer = null;
    }, 250);
  };

  context.addCustomMessageListener(CUSTOM_NAMESPACE, (event) => {
    const result = store.apply(event.data);
    if (result.kind === "invalid") {
      sendInvalidSnapshotResponse(event.senderId, event.data, result.error.message);
    }
  });

  context.addEventListener(
    castGlobal.framework.system.EventType.SENDER_CONNECTED,
    (event) => sendReady(event.senderId),
  );

  const options = new castGlobal.framework.CastReceiverOptions();
  options.customNamespaces = {
    [CUSTOM_NAMESPACE]: castGlobal.framework.system.MessageType.JSON,
  };
  context.start(options);
  return true;
}
