import { REQUIRED_THEME_ROLES } from "../protocol/constants";
import type { SnapshotPlayer, SnapshotPresentation } from "../protocol/types";
import type { PlayerCardViewModel, ReceiverViewModel } from "./viewModel";

interface PreviousPlayerVisualState {
  totalScore: number;
  scoreText: string;
  progressFraction: number;
  targetScore: number;
  targetText: string;
  remainingScore: number;
  remainingScoreText: string;
  winsCount: number;
  winsValueText: string;
  roundsPlayed: number;
  roundsValueText: string;
}

interface AnimatedValueOptions {
  currentText: string;
  currentValue: number;
  kind: string;
  previousText?: string;
  previousValue?: number;
  valueClass: string;
  windowClass: string;
}

interface AnimatedValueResult {
  changed: boolean;
  node: HTMLElement;
}

const PLAYER_TRANSITION_MS = 520;

function element<K extends keyof HTMLElementTagNameMap>(
  tagName: K,
  className?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tagName);
  if (className !== undefined) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function renderAnimatedValue(options: AnimatedValueOptions): AnimatedValueResult {
  const changed =
    options.previousValue !== undefined && options.previousValue !== options.currentValue;
  const window = element("span", `animated-value-window ${options.windowClass}`);

  if (!changed) {
    window.append(element("strong", `${options.valueClass} value-current`, options.currentText));
    return { changed, node: window };
  }

  const direction = options.currentValue > options.previousValue! ? "increase" : "decrease";
  window.classList.add(`is-${direction}`);
  window.dataset.valueAnimation = direction;
  window.dataset.valueKind = options.kind;
  window.append(
    element("strong", `${options.valueClass} value-old`, options.previousText),
    element("strong", `${options.valueClass} value-new`, options.currentText),
  );
  return { changed, node: window };
}

function renderPodium(
  viewModel: ReceiverViewModel,
  previousById: Map<string, PreviousPlayerVisualState>,
): HTMLElement {
  const podium = element("div", "podium-pill");
  viewModel.podium.forEach((player, index) => {
    const place = element("div", "podium-place");
    const previous = previousById.get(player.id);
    const score = renderAnimatedValue({
      currentText: player.display.scoreText,
      currentValue: player.totalScore,
      kind: "podium-score",
      previousText: previous?.scoreText,
      previousValue: previous?.totalScore,
      valueClass: "podium-score",
      windowClass: "podium-score-window",
    });
    place.dataset.rank = String(index + 1);
    place.append(
      element("span", "podium-medal", String(index + 1)),
      element("span", "podium-name", player.display.name),
      score.node,
    );
    podium.append(place);
  });
  return podium;
}

function renderStat(value: AnimatedValueResult, label: string): HTMLElement {
  const stat = element("div", "player-stat");
  stat.append(value.node, element("span", "stat-label", label));
  return stat;
}

function renderCard(
  card: PlayerCardViewModel,
  presentation: SnapshotPresentation,
  targetScore: number,
  compact: boolean,
  previous: PreviousPlayerVisualState | undefined,
  isEntering: boolean,
  animationIndex: number,
): HTMLElement {
  const { player } = card;
  const article = element("article", "player-card");
  article.dataset.playerId = player.id;
  article.classList.toggle("is-behind", player.isRoundBehind);
  article.classList.toggle("is-active", card.isActive);
  article.classList.toggle("is-near-target", player.isNearTarget);
  article.classList.toggle("is-winner", card.status === "winner");
  article.classList.toggle("is-leading", card.status === "leading");
  if (isEntering) {
    article.dataset.playerAnimation = "enter";
    article.style.setProperty("--player-animation-index", String(animationIndex));
  }

  const remainingScore = Math.max(0, targetScore - player.totalScore);
  const showRemainingScore = player.totalScore < targetScore;
  const scoreValue = renderAnimatedValue({
    currentText: player.display.scoreText,
    currentValue: player.totalScore,
    kind: "score",
    previousText: previous?.scoreText,
    previousValue: previous?.totalScore,
    valueClass: "score-value",
    windowClass: "score-window",
  });
  const targetValue = renderAnimatedValue({
    currentText: player.display.targetText,
    currentValue: targetScore,
    kind: "target",
    previousText: previous?.targetText,
    previousValue: previous?.targetScore,
    valueClass: "target-value",
    windowClass: "target-value-window",
  });
  const remainingValue = renderAnimatedValue({
    currentText: player.display.remainingScoreText,
    currentValue: remainingScore,
    kind: "remaining",
    previousText: previous?.remainingScoreText,
    previousValue: previous?.remainingScore,
    valueClass: "remaining-score-value",
    windowClass: "remaining-score",
  });
  const winsValue = renderAnimatedValue({
    currentText: player.display.winsValueText,
    currentValue: player.winsCount,
    kind: "wins",
    previousText: previous?.winsValueText,
    previousValue: previous?.winsCount,
    valueClass: "stat-value",
    windowClass: "stat-value-window",
  });
  const roundsValue = renderAnimatedValue({
    currentText: player.display.roundsValueText,
    currentValue: player.roundsPlayed,
    kind: "rounds",
    previousText: previous?.roundsValueText,
    previousValue: previous?.roundsPlayed,
    valueClass: "stat-value",
    windowClass: "stat-value-window",
  });
  const animatedValues = [scoreValue, targetValue, winsValue, roundsValue];
  if (showRemainingScore) animatedValues.push(remainingValue);
  const hasValueChange = animatedValues.some((value) => value.changed);
  const hasProgressChange =
    previous !== undefined && previous.progressFraction !== player.progressFraction;
  article.classList.toggle("is-value-changing", hasValueChange);
  article.classList.toggle("is-progress-changing", hasProgressChange);

  const progress = element("div", "card-progress");
  const initialProgress = hasProgressChange
    ? (previous?.progressFraction ?? player.progressFraction)
    : player.progressFraction;
  progress.style.width = `${initialProgress * 100}%`;
  progress.dataset.targetWidth = `${player.progressFraction * 100}%`;
  article.append(progress, element("div", "round-behind-marker"));

  const header = element("div", "player-header");
  const identity = element("div", "player-identity");
  identity.append(element("span", "player-name", player.display.name));
  if (showRemainingScore) identity.append(remainingValue.node);
  header.append(identity);

  if (card.status !== "none") {
    const label = card.status === "winner" ? presentation.winnerLabel : presentation.leadingLabel;
    header.append(element("span", `status-badge status-${card.status}`, label));
  }

  const score = element("div", "score-block");
  score.append(scoreValue.node, targetValue.node);

  const stats = element("div", "player-stats");
  stats.append(
    renderStat(
      winsValue,
      compact ? presentation.winsCompactLabel : presentation.winsLabel,
    ),
    renderStat(
      roundsValue,
      compact ? presentation.roundsCompactLabel : presentation.roundsLabel,
    ),
  );

  const main = element("div", "player-main");
  main.append(score, stats);
  article.append(header, main);
  return article;
}

function applyTheme(receiver: HTMLElement, viewModel: ReceiverViewModel): void {
  for (const role of REQUIRED_THEME_ROLES) {
    receiver.style.setProperty(`--color-${role}`, viewModel.theme.roles[role]);
  }
  receiver.dataset.brightness = viewModel.theme.brightness.toLowerCase();
}

function visualState(
  player: SnapshotPlayer,
  targetScore: number,
): PreviousPlayerVisualState {
  return {
    totalScore: player.totalScore,
    scoreText: player.display.scoreText,
    progressFraction: player.progressFraction,
    targetScore,
    targetText: player.display.targetText,
    remainingScore: Math.max(0, targetScore - player.totalScore),
    remainingScoreText: player.display.remainingScoreText,
    winsCount: player.winsCount,
    winsValueText: player.display.winsValueText,
    roundsPlayed: player.roundsPlayed,
    roundsValueText: player.display.roundsValueText,
  };
}

function previousCardPlayers(
  viewModel: ReceiverViewModel | null,
): Map<string, PreviousPlayerVisualState> {
  if (viewModel === null) return new Map();
  return new Map(
    viewModel.cards.map(({ player }) => [
      player.id,
      visualState(player, viewModel.targetScore),
    ]),
  );
}

function previousPodiumPlayers(
  viewModel: ReceiverViewModel | null,
): Map<string, PreviousPlayerVisualState> {
  if (viewModel === null) return new Map();
  return new Map(
    viewModel.podium.map((player) => [player.id, visualState(player, viewModel.targetScore)]),
  );
}

function replacesWholeCardCollection(
  previousViewModel: ReceiverViewModel | null,
  viewModel: ReceiverViewModel,
): boolean {
  return (
    previousViewModel !== null &&
    (previousViewModel.layout !== viewModel.layout ||
      previousViewModel.cards.length !== viewModel.cards.length)
  );
}

function prepareDepartingShell(
  root: HTMLElement,
  previousViewModel: ReceiverViewModel | null,
  viewModel: ReceiverViewModel,
  replaceWholeCollection: boolean,
): HTMLElement | null {
  Array.from(root.children).forEach((child) => {
    if (child.classList.contains("departing-shell")) child.remove();
  });
  if (previousViewModel === null) return null;

  const oldShell = Array.from(root.children).find(
    (child): child is HTMLElement =>
      child instanceof HTMLElement && child.classList.contains("receiver-shell"),
  );
  if (oldShell === undefined) return null;

  const currentIds = new Set(viewModel.cards.map(({ player }) => player.id));
  const departingIds = new Set(
    previousViewModel.cards
      .map(({ player }) => player.id)
      .filter((id) => replaceWholeCollection || !currentIds.has(id)),
  );
  if (departingIds.size === 0) return null;

  oldShell.classList.add("departing-shell");
  oldShell.querySelector(".receiver-header")?.classList.add("is-motion-hidden");
  oldShell.querySelectorAll<HTMLElement>(".players-grid > .player-card").forEach((card) => {
    const playerId = card.dataset.playerId;
    if (playerId !== undefined && departingIds.has(playerId)) {
      card.classList.remove("is-value-changing", "is-progress-changing");
      card.dataset.playerAnimation = "leave";
    } else {
      card.classList.add("is-motion-hidden");
    }
  });
  return oldShell;
}

function startAnimations(receiver: HTMLElement, departingShell: HTMLElement | null): void {
  const run = (): void => {
    receiver.querySelectorAll<HTMLElement>("[data-value-animation]").forEach((value) => {
      value.classList.add("is-running");
    });
    receiver
      .querySelectorAll<HTMLElement>(".is-progress-changing .card-progress")
      .forEach((progress) => {
        const targetWidth = progress.dataset.targetWidth;
        if (targetWidth !== undefined) progress.style.width = targetWidth;
      });
    receiver.querySelectorAll<HTMLElement>('[data-player-animation="enter"]').forEach((card) => {
      card.classList.add("is-running");
    });
    departingShell
      ?.querySelectorAll<HTMLElement>('[data-player-animation="leave"]')
      .forEach((card) => {
        card.classList.add("is-running");
      });
  };

  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(() => requestAnimationFrame(run));
  } else {
    setTimeout(run, 0);
  }
  if (departingShell !== null) {
    setTimeout(() => departingShell.remove(), PLAYER_TRANSITION_MS);
  }
}

export function renderReceiver(
  root: HTMLElement,
  viewModel: ReceiverViewModel,
  previousViewModel: ReceiverViewModel | null = null,
): void {
  const replaceWholeCollection = replacesWholeCardCollection(previousViewModel, viewModel);
  const departingShell = prepareDepartingShell(
    root,
    previousViewModel,
    viewModel,
    replaceWholeCollection,
  );
  const receiver = element("section", "receiver-shell");
  receiver.dataset.layout = viewModel.layout;
  receiver.dataset.playerCount = String(viewModel.cards.length);
  receiver.lang = viewModel.presentation.languageTag;
  receiver.dir = viewModel.presentation.layoutDirection.toLowerCase();
  receiver.style.setProperty(
    "--strip-row-count",
    String(viewModel.layout === "strips" ? Math.max(2, viewModel.cards.length) : 1),
  );
  applyTheme(receiver, viewModel);
  const previousCardsById = previousCardPlayers(previousViewModel);
  const previousPodiumById = previousPodiumPlayers(previousViewModel);
  const previousCardIds = new Set(previousViewModel?.cards.map(({ player }) => player.id) ?? []);

  const header = element("header", "receiver-header");
  const sort = element("div", "header-pill sort-pill");
  sort.append(element("span", "sort-symbol", "↕"), element("span", "sort-label", viewModel.presentation.sortModeLabel));
  header.append(sort, renderPodium(viewModel, previousPodiumById));

  const page = element("div", "header-pill page-pill", viewModel.pageIndicatorText);
  page.classList.toggle("is-hidden", !viewModel.showPageIndicator);
  header.append(page);

  const grid = element("div", "players-grid");
  viewModel.cards.forEach((card, index) => {
    const isEntering =
      previousViewModel === null || replaceWholeCollection || !previousCardIds.has(card.player.id);
    grid.append(
      renderCard(
        card,
        viewModel.presentation,
        viewModel.targetScore,
        viewModel.layout === "compact",
        isEntering ? undefined : previousCardsById.get(card.player.id),
        isEntering,
        index,
      ),
    );
  });

  receiver.append(header, grid);
  root.replaceChildren(...(departingShell === null ? [receiver] : [receiver, departingShell]));
  startAnimations(receiver, departingShell);
}
