import { initializeCastBridge } from "./cast/castBridge";
import { ReceiverStore } from "./state/receiverStore";
import { renderReceiver } from "./ui/render";
import { buildReceiverViewModel, type ReceiverViewModel } from "./ui/viewModel";

export function startReceiver(root: HTMLElement): ReceiverStore {
  const store = new ReceiverStore();
  let previousViewModel: ReceiverViewModel | null = null;
  store.subscribe((snapshot) => {
    const viewModel = buildReceiverViewModel(snapshot);
    renderReceiver(root, viewModel, previousViewModel);
    previousViewModel = viewModel;
  });
  initializeCastBridge(store);
  return store;
}
