import type { SnapshotMessage } from "../protocol/types";
import { ProtocolValidationError, parseSnapshotMessage } from "../protocol/validate";

export type ApplySnapshotResult =
  | { kind: "applied"; snapshot: SnapshotMessage }
  | { kind: "duplicate"; snapshot: SnapshotMessage }
  | { kind: "stale"; snapshot: SnapshotMessage }
  | { kind: "invalid"; error: ProtocolValidationError };

export class ReceiverStore {
  private currentSnapshot: SnapshotMessage | null = null;
  private readonly listeners = new Set<(snapshot: SnapshotMessage) => void>();

  get snapshot(): SnapshotMessage | null {
    return this.currentSnapshot;
  }

  subscribe(listener: (snapshot: SnapshotMessage) => void): () => void {
    this.listeners.add(listener);
    if (this.currentSnapshot !== null) listener(this.currentSnapshot);
    return () => this.listeners.delete(listener);
  }

  apply(input: unknown): ApplySnapshotResult {
    let snapshot: SnapshotMessage;
    try {
      snapshot = parseSnapshotMessage(input);
    } catch (error) {
      const validationError =
        error instanceof ProtocolValidationError
          ? error
          : new ProtocolValidationError("$", "unexpected validation failure");
      return { kind: "invalid", error: validationError };
    }

    const current = this.currentSnapshot;
    if (current?.gameSessionId === snapshot.gameSessionId) {
      if (snapshot.revision < current.revision) return { kind: "stale", snapshot };
      if (snapshot.revision === current.revision) return { kind: "duplicate", snapshot };
    }

    this.currentSnapshot = snapshot;
    for (const listener of this.listeners) listener(snapshot);
    return { kind: "applied", snapshot };
  }
}
