import { PAGE_SIZE } from "../protocol/constants";
import type {
  SnapshotMessage,
  SnapshotPlayer,
  SnapshotPresentation,
  SnapshotTheme,
} from "../protocol/types";

export type ReceiverLayout = "strips" | "full" | "compact";
export type PlayerStatus = "winner" | "leading" | "none";

export interface PlayerCardViewModel {
  player: SnapshotPlayer;
  status: PlayerStatus;
  isActive: boolean;
}

export interface ReceiverViewModel {
  targetScore: number;
  layout: ReceiverLayout;
  pageIndex: number;
  pageCount: number;
  pageIndicatorText: string;
  showPageIndicator: boolean;
  emptySlotCount: number;
  cards: PlayerCardViewModel[];
  podium: SnapshotPlayer[];
  presentation: SnapshotPresentation;
  theme: SnapshotTheme;
}

function pageForPlayer(playerId: string | null, orderedIds: string[]): number | null {
  if (playerId === null) return null;
  const index = orderedIds.indexOf(playerId);
  return index < 0 ? null : Math.floor(index / PAGE_SIZE);
}

export function layoutForPlayerCount(playerCount: number): ReceiverLayout {
  if (playerCount <= 4) return "strips";
  if (playerCount <= 6) return "full";
  return "compact";
}

export function buildReceiverViewModel(snapshot: SnapshotMessage): ReceiverViewModel {
  const { game, players, presentation, theme } = snapshot.payload;
  const pageCount = Math.ceil(players.length / PAGE_SIZE);
  const requestedPage = Math.min(game.requestedPageIndex, pageCount - 1);
  const activePage = pageForPlayer(game.activeScoringPlayerId, game.orderedPlayerIds);
  const transientPage = pageForPlayer(game.transientFocusPlayerId, game.orderedPlayerIds);
  const pageIndex = activePage ?? transientPage ?? requestedPage;
  const orderedPlayers = game.orderedPlayerIds.map((id) => {
    const player = players.find((candidate) => candidate.id === id);
    if (player === undefined) throw new Error(`Validated player ${id} is missing`);
    return player;
  });
  const visiblePlayers =
    pageCount > 1
      ? orderedPlayers.slice(pageIndex * PAGE_SIZE, (pageIndex + 1) * PAGE_SIZE)
      : orderedPlayers;
  const winners = new Set(game.winnerPlayerIds);
  const leaders = new Set(game.leaderPlayerIds);
  const podiumById = new Map(players.map((player) => [player.id, player]));
  const layout = pageCount > 1 ? "compact" : layoutForPlayerCount(players.length);
  const capacity =
    layout === "compact" ? PAGE_SIZE : layout === "full" ? 6 : Math.max(2, players.length);

  return {
    targetScore: game.targetScore,
    layout,
    pageIndex,
    pageCount,
    pageIndicatorText: presentation.pageIndicatorTexts[pageIndex] ?? "",
    showPageIndicator: pageCount > 1,
    emptySlotCount: Math.max(0, capacity - visiblePlayers.length),
    cards: visiblePlayers.map((player) => ({
      player,
      status: winners.has(player.id) ? "winner" : leaders.has(player.id) ? "leading" : "none",
      isActive: game.activeScoringPlayerId === player.id,
    })),
    podium: game.podiumPlayerIds
      .map((id) => podiumById.get(id))
      .filter((player): player is SnapshotPlayer => player !== undefined),
    presentation,
    theme,
  };
}
