import {
  PAGE_SIZE,
  PROTOCOL_VERSION,
  REQUIRED_THEME_ROLES,
  type ThemeRole,
} from "./constants";
import type {
  LayoutDirection,
  SnapshotGame,
  SnapshotMessage,
  SnapshotPlayer,
  SnapshotPlayerDisplay,
  SnapshotPresentation,
  SnapshotTheme,
  SortMode,
  ThemeBrightness,
} from "./types";

export class ProtocolValidationError extends Error {
  constructor(
    readonly path: string,
    message: string,
  ) {
    super(`${path}: ${message}`);
    this.name = "ProtocolValidationError";
  }
}

function fail(path: string, message: string): never {
  throw new ProtocolValidationError(path, message);
}

function asObject(value: unknown, path: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail(path, "expected an object");
  }
  return value as Record<string, unknown>;
}

function asString(value: unknown, path: string): string {
  if (typeof value !== "string" || value.length === 0) {
    fail(path, "expected a non-empty string");
  }
  return value;
}

function asInteger(value: unknown, path: string, minimum = Number.MIN_SAFE_INTEGER): number {
  if (!Number.isSafeInteger(value) || (value as number) < minimum) {
    fail(path, `expected an integer >= ${minimum}`);
  }
  return value as number;
}

function asBoolean(value: unknown, path: string): boolean {
  if (typeof value !== "boolean") fail(path, "expected a boolean");
  return value;
}

function asNullableString(value: unknown, path: string): string | null {
  if (value === undefined || value === null) return null;
  return asString(value, path);
}

function asStringArray(value: unknown, path: string): string[] {
  if (!Array.isArray(value)) fail(path, "expected an array");
  return value.map((entry, index) => asString(entry, `${path}[${index}]`));
}

function asUniqueStringArray(value: unknown, path: string): string[] {
  const result = asStringArray(value, path);
  if (new Set(result).size !== result.length) fail(path, "IDs must be unique");
  return result;
}

function asEnum<T extends string>(value: unknown, allowed: readonly T[], path: string): T {
  if (typeof value !== "string" || !allowed.includes(value as T)) {
    fail(path, `expected one of ${allowed.join(", ")}`);
  }
  return value as T;
}

function parseGame(value: unknown): SnapshotGame {
  const path = "$.payload.game";
  const game = asObject(value, path);
  return {
    targetScore: asInteger(game.targetScore, `${path}.targetScore`, 1),
    sortMode: asEnum<SortMode>(
      game.sortMode,
      ["LIST", "LEADERBOARD", "NEXT_TURN"],
      `${path}.sortMode`,
    ),
    orderedPlayerIds: asUniqueStringArray(game.orderedPlayerIds, `${path}.orderedPlayerIds`),
    podiumPlayerIds: asUniqueStringArray(game.podiumPlayerIds, `${path}.podiumPlayerIds`),
    winnerPlayerIds: asUniqueStringArray(game.winnerPlayerIds, `${path}.winnerPlayerIds`),
    leaderPlayerIds: asUniqueStringArray(game.leaderPlayerIds, `${path}.leaderPlayerIds`),
    requestedPageIndex: asInteger(game.requestedPageIndex, `${path}.requestedPageIndex`, 0),
    activeScoringPlayerId: asNullableString(
      game.activeScoringPlayerId,
      `${path}.activeScoringPlayerId`,
    ),
    transientFocusPlayerId: asNullableString(
      game.transientFocusPlayerId,
      `${path}.transientFocusPlayerId`,
    ),
  };
}

function parsePresentation(value: unknown): SnapshotPresentation {
  const path = "$.payload.presentation";
  const presentation = asObject(value, path);
  return {
    languageTag: asString(presentation.languageTag, `${path}.languageTag`),
    layoutDirection: asEnum<LayoutDirection>(
      presentation.layoutDirection,
      ["LTR", "RTL"],
      `${path}.layoutDirection`,
    ),
    sortModeLabel: asString(presentation.sortModeLabel, `${path}.sortModeLabel`),
    winnerLabel: asString(presentation.winnerLabel, `${path}.winnerLabel`),
    leadingLabel: asString(presentation.leadingLabel, `${path}.leadingLabel`),
    winsLabel: asString(presentation.winsLabel, `${path}.winsLabel`),
    winsCompactLabel: asString(
      presentation.winsCompactLabel,
      `${path}.winsCompactLabel`,
    ),
    roundsLabel: asString(presentation.roundsLabel, `${path}.roundsLabel`),
    roundsCompactLabel: asString(
      presentation.roundsCompactLabel,
      `${path}.roundsCompactLabel`,
    ),
    pageIndicatorTexts: asStringArray(
      presentation.pageIndicatorTexts,
      `${path}.pageIndicatorTexts`,
    ),
  };
}

function parseTheme(value: unknown): SnapshotTheme {
  const path = "$.payload.theme";
  const theme = asObject(value, path);
  const rawRoles = asObject(theme.roles, `${path}.roles`);
  const roles = {} as Record<ThemeRole, string>;
  for (const role of REQUIRED_THEME_ROLES) {
    const color = asString(rawRoles[role], `${path}.roles.${role}`);
    if (!/^#[\dA-Fa-f]{6}$/.test(color)) {
      fail(`${path}.roles.${role}`, "expected a #RRGGBB color");
    }
    roles[role] = color;
  }
  return {
    brightness: asEnum<ThemeBrightness>(
      theme.brightness,
      ["LIGHT", "DARK"],
      `${path}.brightness`,
    ),
    roles,
  };
}

function parseDisplay(value: unknown, path: string): SnapshotPlayerDisplay {
  const display = asObject(value, path);
  return {
    name: asString(display.name, `${path}.name`),
    scoreText: asString(display.scoreText, `${path}.scoreText`),
    targetText: asString(display.targetText, `${path}.targetText`),
    remainingScoreText: asString(display.remainingScoreText, `${path}.remainingScoreText`),
    winsValueText: asString(display.winsValueText, `${path}.winsValueText`),
    roundsValueText: asString(display.roundsValueText, `${path}.roundsValueText`),
  };
}

function parsePlayers(value: unknown): SnapshotPlayer[] {
  const path = "$.payload.players";
  if (!Array.isArray(value) || value.length === 0) fail(path, "expected at least one player");

  const players = value.map((entry, index): SnapshotPlayer => {
    const playerPath = `${path}[${index}]`;
    const player = asObject(entry, playerPath);
    const progressFraction = player.progressFraction;
    if (
      typeof progressFraction !== "number" ||
      !Number.isFinite(progressFraction) ||
      progressFraction < 0 ||
      progressFraction > 1
    ) {
      fail(`${playerPath}.progressFraction`, "expected a finite number from 0 through 1");
    }
    return {
      id: asString(player.id, `${playerPath}.id`),
      position: asInteger(player.position, `${playerPath}.position`, 0),
      totalScore: asInteger(player.totalScore, `${playerPath}.totalScore`),
      roundsPlayed: asInteger(player.roundsPlayed, `${playerPath}.roundsPlayed`, 0),
      winsCount: asInteger(player.winsCount, `${playerPath}.winsCount`, 0),
      progressFraction,
      isRoundBehind: asBoolean(player.isRoundBehind, `${playerPath}.isRoundBehind`),
      isNearTarget: asBoolean(player.isNearTarget, `${playerPath}.isNearTarget`),
      display: parseDisplay(player.display, `${playerPath}.display`),
    };
  });

  const ids = players.map((player) => player.id);
  if (new Set(ids).size !== ids.length) fail(path, "player IDs must be unique");
  return players;
}

function validateReferences(game: SnapshotGame, players: SnapshotPlayer[]): void {
  const playerIds = players.map((player) => player.id);
  const expectedIds = [...playerIds].sort();
  const orderedIds = [...game.orderedPlayerIds].sort();
  if (
    expectedIds.length !== orderedIds.length ||
    expectedIds.some((id, index) => id !== orderedIds[index])
  ) {
    fail("$.payload.game.orderedPlayerIds", "expected an exact permutation of players[].id");
  }

  if (game.podiumPlayerIds.length > 3) {
    fail("$.payload.game.podiumPlayerIds", "expected at most 3 IDs");
  }

  const knownIds = new Set(playerIds);
  const referencedIds = [
    ...game.podiumPlayerIds,
    ...game.winnerPlayerIds,
    ...game.leaderPlayerIds,
    game.activeScoringPlayerId,
    game.transientFocusPlayerId,
  ].filter((id): id is string => id !== null);
  for (const id of referencedIds) {
    if (!knownIds.has(id)) fail("$.payload.game", `unknown referenced player ID: ${id}`);
  }
}

export function parseSnapshotMessage(input: unknown): SnapshotMessage {
  let decoded = input;
  if (typeof input === "string") {
    try {
      decoded = JSON.parse(input) as unknown;
    } catch {
      fail("$", "expected valid JSON");
    }
  }

  const envelope = asObject(decoded, "$");
  const protocolVersion = asInteger(envelope.protocolVersion, "$.protocolVersion", 1);
  if (protocolVersion !== PROTOCOL_VERSION) fail("$.protocolVersion", "expected 1");
  if (envelope.messageType !== "snapshot") fail("$.messageType", "expected snapshot");

  const payload = asObject(envelope.payload, "$.payload");
  const game = parseGame(payload.game);
  const presentation = parsePresentation(payload.presentation);
  const theme = parseTheme(payload.theme);
  const players = parsePlayers(payload.players);
  validateReferences(game, players);

  const expectedPageCount = Math.ceil(players.length / PAGE_SIZE);
  if (presentation.pageIndicatorTexts.length !== expectedPageCount) {
    fail(
      "$.payload.presentation.pageIndicatorTexts",
      `expected ${expectedPageCount} entries for ${players.length} players`,
    );
  }

  const capabilities =
    envelope.capabilities === undefined
      ? []
      : asStringArray(envelope.capabilities, "$.capabilities");

  return {
    protocolVersion: 1,
    messageType: "snapshot",
    messageId: asString(envelope.messageId, "$.messageId"),
    gameSessionId: asString(envelope.gameSessionId, "$.gameSessionId"),
    revision: asInteger(envelope.revision, "$.revision", 0),
    capabilities,
    payload: {
      game,
      presentation,
      theme,
      players,
    },
  };
}
